export function wrapInlineFlagsGroup(
	data: T.InlineFlagsGroup & { readonly $other?: T.InlineFlagsGroup | readonly T.InlineFlagsGroup[] },
	tree: TreeHandle
): T.InlineFlagsGroup.Parsed {
	if (typeof data === 'number') return data as unknown as T.InlineFlagsGroup.Parsed;
	const node = _keepModelledSlots(data, [
		'_inline_flags_group_enable',
		'_inline_flags_group_toggle',
		'_inline_flags_group_disable'
	]);
	const kindKeyed = _firstKindKeyedWrapChild(node, [
		'inline_flags_group_enable',
		'inline_flags_group_toggle',
		'inline_flags_group_disable'
	]) as T.InlineFlagsGroup | readonly T.InlineFlagsGroup[] | undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, [
			'inline_flags_group_enable',
			'inline_flags_group_toggle',
			'inline_flags_group_disable'
		]);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.InlineFlagsGroup>(node as T.InlineFlagsGroup, tree) as unknown as T.InlineFlagsGroup.Parsed;
	}
	return hydrateChild<T.InlineFlagsGroup>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

